import{_ as e,o as a,c as s,a2 as l}from"./chunks/framework.DIWxYxwh.js";const x=JSON.parse('{"title":"MoE vs Dense","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/MoE和Dense架构对比.md","filePath":"LLM推理/MoE和Dense架构对比.md","lastUpdated":1792058828000}'),d={name:"LLM推理/MoE和Dense架构对比.md"};function i(n,t,r,h,g,o){return a(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="moe-vs-dense" tabindex="-1">MoE vs Dense <a class="header-anchor" href="#moe-vs-dense" aria-label="Permalink to &quot;MoE vs Dense&quot;">​</a></h1><h2 id="_1-测试背景" tabindex="-1">1. 测试背景 <a class="header-anchor" href="#_1-测试背景" aria-label="Permalink to &quot;1. 测试背景&quot;">​</a></h2><p>本次对比两款 FP8 模型在不同并发下的推理性能：</p><ul><li><strong>Dense：</strong> Qwen3.8-27B-FP8</li><li><strong>MoE：</strong> Qwen3.6-35B-A3B-FP8</li></ul><p>两者都使用 FP8 权重，但架构不同。Dense 的 FFN 参数每个 token 都会参与计算；MoE 通过专家路由，仅激活部分专家。因此，总参数量不能直接代表每 token 的计算量。</p><h3 id="测试环境" tabindex="-1">测试环境 <a class="header-anchor" href="#测试环境" aria-label="Permalink to &quot;测试环境&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>配置</th></tr></thead><tbody><tr><td>CPU</td><td>Intel Core i9-14900K</td></tr><tr><td>内存</td><td>64 GB</td></tr><tr><td>GPU</td><td>NVIDIA RTX 4090</td></tr><tr><td>推理框架</td><td>vLLM 0.31.0</td></tr><tr><td>Dense 模型</td><td>Qwen3.8-27B-FP8</td></tr><tr><td>MoE 模型</td><td>Qwen3.6-35B-A3B-FP8</td></tr><tr><td>推理模式</td><td>Eager，未使用 CUDA Graph</td></tr><tr><td>API</td><td><code>/v1/chat/completions</code></td></tr></tbody></table><p>Dense 使用 FP8 权重，具体量化执行路径以 vLLM 启动日志为准。若日志显示 Marlin weight-only 路径，应在环境说明中注明。</p><h3 id="测试方法" tabindex="-1">测试方法 <a class="header-anchor" href="#测试方法" aria-label="Permalink to &quot;测试方法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>配置</th></tr></thead><tbody><tr><td>每个模型请求数</td><td>128</td></tr><tr><td>并发数</td><td>1、4、8、16</td></tr><tr><td>每种并发请求数</td><td>32</td></tr><tr><td>目标输入长度</td><td>512 tokens</td></tr><tr><td>输出长度</td><td>128 tokens</td></tr><tr><td>Think 模式</td><td>开启</td></tr><tr><td>失败请求</td><td>0</td></tr><tr><td>请求提交</td><td>全部提交，客户端限制同时在途请求数</td></tr></tbody></table><p>两款模型均包含视觉编码器，但本次只测试文本输入。</p><h2 id="_2-模型结构差异" tabindex="-1">2. 模型结构差异 <a class="header-anchor" href="#_2-模型结构差异" aria-label="Permalink to &quot;2. 模型结构差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">Dense：Qwen3.8-27B-FP8</th><th style="text-align:right;">MoE：Qwen3.6-35B-A3B-FP8</th></tr></thead><tbody><tr><td>总参数量</td><td style="text-align:right;">27B</td><td style="text-align:right;">约 35B</td></tr><tr><td>每 token 激活参数量</td><td style="text-align:right;">Dense 参数参与计算</td><td style="text-align:right;">约 3B</td></tr><tr><td>Transformer 层数</td><td style="text-align:right;">64</td><td style="text-align:right;">40</td></tr><tr><td>Hidden size</td><td style="text-align:right;">5120</td><td style="text-align:right;">2048</td></tr><tr><td>全注意力层</td><td style="text-align:right;">16</td><td style="text-align:right;">10</td></tr><tr><td>线性注意力层</td><td style="text-align:right;">48</td><td style="text-align:right;">30</td></tr><tr><td>全注意力 KV heads</td><td style="text-align:right;">4</td><td style="text-align:right;">2</td></tr><tr><td>Attention head dimension</td><td style="text-align:right;">256</td><td style="text-align:right;">256</td></tr><tr><td>FFN / Expert 中间维度</td><td style="text-align:right;">17408</td><td style="text-align:right;">512</td></tr><tr><td>路由专家</td><td style="text-align:right;">无</td><td style="text-align:right;">256 个，每 token 选 8 个</td></tr><tr><td>共享专家</td><td style="text-align:right;">无</td><td style="text-align:right;">1 个</td></tr></tbody></table><p>主要区别在于每 token 的计算路径：</p><ul><li><strong>Dense：</strong> 每个 token 都经过 Dense FFN，计算量相对稳定。</li><li><strong>MoE：</strong> 每个 token 只激活部分路由专家，并额外经过共享专家。</li></ul><p>MoE 需要存储所有专家权重，但单 token 不需要计算所有专家。因此，总参数量更大的 MoE 仍可能具有更低的单 token 计算量。</p><h2 id="_3-单请求解码-为什么速度接近" tabindex="-1">3. 单请求解码：为什么速度接近？ <a class="header-anchor" href="#_3-单请求解码-为什么速度接近" aria-label="Permalink to &quot;3. 单请求解码：为什么速度接近？&quot;">​</a></h2><p>TPOT（Time Per Output Token）表示生成阶段平均每个输出 token 所需的时间。TPOT 越低，单请求解码速度越快。</p><h3 id="tpot-实测结果" tabindex="-1">TPOT 实测结果 <a class="header-anchor" href="#tpot-实测结果" aria-label="Permalink to &quot;TPOT 实测结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">并发数</th><th style="text-align:right;">Dense TPOT</th><th style="text-align:right;">MoE TPOT</th><th>对比</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">33.98 ms</td><td style="text-align:right;">35.02 ms</td><td>Dense 快约 3%</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:right;">37.19 ms</td><td style="text-align:right;">36.03 ms</td><td>MoE 快约 3%</td></tr><tr><td style="text-align:right;">8</td><td style="text-align:right;">40.73 ms</td><td style="text-align:right;">36.86 ms</td><td>MoE 快约 9.5%</td></tr><tr><td style="text-align:right;">16</td><td style="text-align:right;">51.88 ms</td><td style="text-align:right;">41.36 ms</td><td>MoE 快约 20.3%</td></tr></tbody></table><p>并发为 1 时，两者 TPOT 仅相差约 1 ms。也就是说，在当前硬件、推理框架和执行配置下，<strong>Dense 与 MoE 的单请求解码速度基本处于同一水平</strong>。</p><p>这不代表两者计算量相同，而是说明实际解码速度还受到权重访存、kernel 效率、量化实现和模型结构等因素影响。</p><h3 id="dense-的权重带宽估算" tabindex="-1">Dense 的权重带宽估算 <a class="header-anchor" href="#dense-的权重带宽估算" aria-label="Permalink to &quot;Dense 的权重带宽估算&quot;">​</a></h3><p>假设 Dense 实际加载权重约 29.34 GiB，换算为 GB：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>29.34 GiB × 1.0737 ≈ 31.5 GB</span></span></code></pre></div><p>RTX 4090 理论显存带宽约 1008 GB/s。若一次解码迭代需要读取全部权重，则理想带宽下限为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T_min = 31.5 GB / 1008 GB/s × 1000 ms/s</span></span>
<span class="line"><span>      ≈ 31.3 ms</span></span></code></pre></div><p>该估算与 Dense 在并发 1 时实测的 33.98 ms TPOT 接近。但它只是简化估算，不能据此断定 Dense 完全受显存带宽限制。29.34 GiB 应来自实际权重规模，而非单纯按参数量推算；实际读取量还会受缓存、kernel 实现和批处理方式影响。</p><p>FP8 可降低权重存储和访存开销，但实际占用还包括量化 scale、未量化参数及其他模型状态，因此不能简单认为所有权重都严格占用每参数 1 byte。</p><h2 id="_4-ffn-理论计算量-moe-为什么更低" tabindex="-1">4. FFN 理论计算量：MoE 为什么更低？ <a class="header-anchor" href="#_4-ffn-理论计算量-moe-为什么更低" aria-label="Permalink to &quot;4. FFN 理论计算量：MoE 为什么更低？&quot;">​</a></h2><p>可用以下简化公式估算 FFN 主要线性投影的 FLOPs：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>F_FFN ≈ 2 × 3 × d × f × L</span></span></code></pre></div><p>其中：</p><ul><li><code>d</code>：隐藏层维度</li><li><code>f</code>：FFN 或专家中间维度</li><li><code>L</code>：层数</li><li><code>2</code>：一次乘加按 2 FLOPs 计</li><li><code>3</code>：SwiGLU 的 gate、up、down 三个线性投影</li></ul><h3 id="dense" tabindex="-1">Dense <a class="header-anchor" href="#dense" aria-label="Permalink to &quot;Dense&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>F_Dense ≈ 2 × 3 × 5120 × 17408 × 64</span></span>
<span class="line"><span>        ≈ 34.2 GFLOPs/token</span></span></code></pre></div><h3 id="moe" tabindex="-1">MoE <a class="header-anchor" href="#moe" aria-label="Permalink to &quot;MoE&quot;">​</a></h3><p>MoE 每层每 token 激活 8 个路由专家和 1 个共享专家：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>F_MoE ≈ 2 × 3 × 2048 × 512 × 9 × 40</span></span>
<span class="line"><span>      ≈ 2.26 GFLOPs/token</span></span></code></pre></div><p>两者近似计算量之比：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>R = F_Dense / F_MoE</span></span>
<span class="line"><span>  = 34.2 / 2.26</span></span>
<span class="line"><span>  ≈ 15.1</span></span></code></pre></div><p>按这组假设，Dense 的 FFN 主要线性投影计算量约为 MoE 的 15.1 倍。</p><h3 id="为什么计算量相差-15-1-倍-速度却没有相差-15-1-倍" tabindex="-1">为什么计算量相差 15.1 倍，速度却没有相差 15.1 倍？ <a class="header-anchor" href="#为什么计算量相差-15-1-倍-速度却没有相差-15-1-倍" aria-label="Permalink to &quot;为什么计算量相差 15.1 倍，速度却没有相差 15.1 倍？&quot;">​</a></h3><p>这里的 15.1 倍，<strong>只代表所选 FFN 线性投影的理论 FLOPs 比值，不是完整模型总计算量比值，更不是实测推理速度比值。</strong> 原因如下：</p><ol><li><strong>计算量只是推理耗时的一部分。</strong> 完整推理还包括注意力、线性注意力状态更新、归一化、残差、路由、词表输出等，FFN FLOPs 比值不能代表整个模型。</li><li><strong>GPU 并非只受计算量限制。</strong> 若某阶段受显存带宽限制，减少 FLOPs 不一定按比例缩短耗时；若受计算吞吐限制，降低计算量可能收益更明显。</li><li><strong>FP8 理论计算量不等于实际执行效率。</strong> 两款模型虽都是 FP8，但 kernel、矩阵尺寸、量化 scale 处理和硬件执行路径可能不同。</li><li><strong>MoE 还需专家路由与调度。</strong> 专家矩阵较小，未必总能达到 GPU 最高计算效率；不同并发下，专家批处理效率也会变化。</li><li><strong>并发会改变计算与访存利用率。</strong> 增加并发可提高批处理效率，但也会增加显存访问、调度和资源竞争。Dense 与 MoE 对并发的响应不同，速度差距会随并发变化。</li></ol><p>因此，这个计算仅用于解释：<strong>MoE 结构具有更低的每 token FFN 计算量潜力。</strong> 这种优势能转化成多少实际速度，需以实测 TPOT、吞吐量和延迟为准。</p><h2 id="_5-并发吞吐量-moe-优势逐渐扩大" tabindex="-1">5. 并发吞吐量：MoE 优势逐渐扩大 <a class="header-anchor" href="#_5-并发吞吐量-moe-优势逐渐扩大" aria-label="Permalink to &quot;5. 并发吞吐量：MoE 优势逐渐扩大&quot;">​</a></h2><p>总吞吐量表示单位时间内所有请求生成的输出 token 数。并发增加后，GPU 可在一次迭代中处理更多请求，但不同模型的扩展效率并不相同。</p><h3 id="总输出吞吐量" tabindex="-1">总输出吞吐量 <a class="header-anchor" href="#总输出吞吐量" aria-label="Permalink to &quot;总输出吞吐量&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">并发数</th><th style="text-align:right;">Dense</th><th style="text-align:right;">MoE</th><th style="text-align:right;">MoE / Dense</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">28.00 tok/s</td><td style="text-align:right;">27.85 tok/s</td><td style="text-align:right;">0.99×</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:right;">91.56 tok/s</td><td style="text-align:right;">106.84 tok/s</td><td style="text-align:right;">1.17×</td></tr><tr><td style="text-align:right;">8</td><td style="text-align:right;">156.07 tok/s</td><td style="text-align:right;">208.31 tok/s</td><td style="text-align:right;">1.33×</td></tr><tr><td style="text-align:right;">16</td><td style="text-align:right;">234.23 tok/s</td><td style="text-align:right;">360.59 tok/s</td><td style="text-align:right;">1.54×</td></tr></tbody></table><p>结果显示：</p><ul><li>并发 1 时，两款模型总吞吐量几乎相同。</li><li>并发 4 时，MoE 领先约 17%。</li><li>并发 8 时，领先约 33%。</li><li>并发 16 时，MoE 达到 360.59 tok/s，约为 Dense 的 <strong>1.54 倍</strong>。</li></ul><h3 id="线性扩展效率" tabindex="-1">线性扩展效率 <a class="header-anchor" href="#线性扩展效率" aria-label="Permalink to &quot;线性扩展效率&quot;">​</a></h3><p>以并发 1 的吞吐量为基准，定义线性扩展效率：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>E_C = T_C / (C × T_1) × 100%</span></span></code></pre></div><p>其中：</p><ul><li><code>T_C</code>：并发数为 <code>C</code> 时的总吞吐量</li><li><code>T_1</code>：并发数为 1 时的总吞吐量</li><li><code>C</code>：并发数</li></ul><table tabindex="0"><thead><tr><th style="text-align:right;">并发数</th><th style="text-align:right;">Dense 扩展效率</th><th style="text-align:right;">MoE 扩展效率</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">100%</td><td style="text-align:right;">100%</td></tr><tr><td style="text-align:right;">4</td><td style="text-align:right;">81.8%</td><td style="text-align:right;">95.9%</td></tr><tr><td style="text-align:right;">8</td><td style="text-align:right;">69.7%</td><td style="text-align:right;">93.5%</td></tr><tr><td style="text-align:right;">16</td><td style="text-align:right;">52.3%</td><td style="text-align:right;">80.9%</td></tr></tbody></table><p>Dense 的扩展效率随并发上升明显下降；MoE 在并发 16 时仍保持约 80.9%。</p><p>这说明在当前配置下，MoE 更能将增加的并发请求转化为额外吞吐量。可能原因包括每 token 激活参数较少、Dense 权重访存压力较大，以及两者在量化 kernel 和批处理调度方面的差异。现有数据能展示这一现象，但不能证明某一因素是唯一原因。</p><h2 id="_6-延迟表现-吞吐量提升不等于所有延迟都下降" tabindex="-1">6. 延迟表现：吞吐量提升不等于所有延迟都下降 <a class="header-anchor" href="#_6-延迟表现-吞吐量提升不等于所有延迟都下降" aria-label="Permalink to &quot;6. 延迟表现：吞吐量提升不等于所有延迟都下降&quot;">​</a></h2><p>除 TPOT 和吞吐量外，还需关注 TTFT、ITL 和端到端延迟：</p><ul><li><strong>TTFT：</strong> 从请求开始到收到第一个输出 token 的时间。</li><li><strong>TPOT：</strong> 生成阶段平均每个输出 token 的时间。</li><li><strong>ITL：</strong> 相邻输出 token 之间的间隔。</li><li><strong>E2E：</strong> 请求从开始到生成完成的总耗时。</li></ul><h3 id="延迟实测结果" tabindex="-1">延迟实测结果 <a class="header-anchor" href="#延迟实测结果" aria-label="Permalink to &quot;延迟实测结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">并发</th><th>模型</th><th style="text-align:right;">平均 TTFT</th><th style="text-align:right;">TTFT 中位数</th><th style="text-align:right;">TTFT P99</th><th style="text-align:right;">平均 TPOT</th><th style="text-align:right;">ITL P99</th><th style="text-align:right;">平均 E2E</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>Dense</td><td style="text-align:right;">256 ms</td><td style="text-align:right;">261 ms</td><td style="text-align:right;">291 ms</td><td style="text-align:right;">33.98 ms</td><td style="text-align:right;">35.4 ms</td><td style="text-align:right;">4.57 s</td></tr><tr><td style="text-align:right;">1</td><td>MoE</td><td style="text-align:right;">148 ms</td><td style="text-align:right;">85 ms</td><td style="text-align:right;">1473 ms</td><td style="text-align:right;">35.02 ms</td><td style="text-align:right;">70.6 ms</td><td style="text-align:right;">4.60 s</td></tr><tr><td style="text-align:right;">4</td><td>Dense</td><td style="text-align:right;">869 ms</td><td style="text-align:right;">885 ms</td><td style="text-align:right;">965 ms</td><td style="text-align:right;">37.19 ms</td><td style="text-align:right;">74 ms</td><td style="text-align:right;">5.59 s</td></tr><tr><td style="text-align:right;">4</td><td>MoE</td><td style="text-align:right;">217 ms</td><td style="text-align:right;">159 ms</td><td style="text-align:right;">895 ms</td><td style="text-align:right;">36.03 ms</td><td style="text-align:right;">72 ms</td><td style="text-align:right;">4.79 s</td></tr><tr><td style="text-align:right;">8</td><td>Dense</td><td style="text-align:right;">1.38 s</td><td style="text-align:right;">1.42 s</td><td style="text-align:right;">1.86 s</td><td style="text-align:right;">40.73 ms</td><td style="text-align:right;">101 ms</td><td style="text-align:right;">6.55 s</td></tr><tr><td style="text-align:right;">8</td><td>MoE</td><td style="text-align:right;">232 ms</td><td style="text-align:right;">217 ms</td><td style="text-align:right;">569 ms</td><td style="text-align:right;">36.86 ms</td><td style="text-align:right;">73 ms</td><td style="text-align:right;">4.91 s</td></tr><tr><td style="text-align:right;">16</td><td>Dense</td><td style="text-align:right;">2.12 s</td><td style="text-align:right;">2.01 s</td><td style="text-align:right;">3.61 s</td><td style="text-align:right;">51.88 ms</td><td style="text-align:right;">660 ms</td><td style="text-align:right;">8.71 s</td></tr><tr><td style="text-align:right;">16</td><td>MoE</td><td style="text-align:right;">362 ms</td><td style="text-align:right;">296 ms</td><td style="text-align:right;">897 ms</td><td style="text-align:right;">41.36 ms</td><td style="text-align:right;">116 ms</td><td style="text-align:right;">5.61 s</td></tr></tbody></table><p>并发 16 时，Dense 平均 TTFT 达 2.12 秒，MoE 为 362 ms；Dense 平均 E2E 为 8.71 秒，MoE 为 5.61 秒。这与吞吐量结果一致：MoE 在较高并发下整体表现更好。</p><p>TPOT 和 ITL 不能混为一谈。TPOT 是生成阶段的平均时间指标，ITL 反映 token 间隔分布。并发调度可能导致个别 token 间隔明显变长，因此不能仅凭平均 TPOT 推断尾部 ITL。</p><p>每个并发级别只有 32 个请求，P99 主要用于观察尾延迟现象，不宜直接视为稳定的生产环境尾延迟指标。</p><h2 id="_7-kv-cache-理论开销与运行时容量" tabindex="-1">7. KV Cache：理论开销与运行时容量 <a class="header-anchor" href="#_7-kv-cache-理论开销与运行时容量" aria-label="Permalink to &quot;7. KV Cache：理论开销与运行时容量&quot;">​</a></h2><p>两款模型都采用混合注意力结构，包括线性注意力层和全注意力层，因此不能把所有 Transformer 层都视为标准全注意力层来计算 KV Cache。</p><p>对于全注意力部分，假设 K/V 元素各占 1 byte，每个 token 的 K/V 存储量可估算为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>M_KV = N_full × N_KVheads × D_head × 2 × B</span></span></code></pre></div><p>其中：</p><ul><li><code>N_full</code>：全注意力层数</li><li><code>N_KVheads</code>：每层 KV heads 数量</li><li><code>D_head</code>：每个 head 的维度</li><li><code>2</code>：分别存储 Key 和 Value</li><li><code>B</code>：每个元素占用的字节数，此处假设为 1</li></ul><h3 id="dense-1" tabindex="-1">Dense <a class="header-anchor" href="#dense-1" aria-label="Permalink to &quot;Dense&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>M_KV = 16 × 4 × 256 × 2 × 1</span></span>
<span class="line"><span>     = 32768 bytes/token</span></span>
<span class="line"><span>     ≈ 32 KiB/token</span></span></code></pre></div><h3 id="moe-1" tabindex="-1">MoE <a class="header-anchor" href="#moe-1" aria-label="Permalink to &quot;MoE&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>M_KV = 10 × 2 × 256 × 2 × 1</span></span>
<span class="line"><span>     = 10240 bytes/token</span></span>
<span class="line"><span>     ≈ 10 KiB/token</span></span></code></pre></div><h3 id="vllm-报告的缓存容量" tabindex="-1">vLLM 报告的缓存容量 <a class="header-anchor" href="#vllm-报告的缓存容量" aria-label="Permalink to &quot;vLLM 报告的缓存容量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">Dense</th><th style="text-align:right;">MoE</th></tr></thead><tbody><tr><td>全注意力层数</td><td style="text-align:right;">16</td><td style="text-align:right;">10</td></tr><tr><td>KV heads</td><td style="text-align:right;">4</td><td style="text-align:right;">2</td></tr><tr><td>全注意力 K/V 理论开销</td><td style="text-align:right;">32 KiB/token</td><td style="text-align:right;">10 KiB/token</td></tr><tr><td>vLLM 报告缓存容量</td><td style="text-align:right;">11.22 GiB</td><td style="text-align:right;">5.88 GiB</td></tr><tr><td>vLLM 报告缓存 token 数</td><td style="text-align:right;">239,616</td><td style="text-align:right;">376,320</td></tr></tbody></table><p>以上理论值只覆盖全注意力层的 K/V，不包括线性注意力状态缓存。实际运行时容量还会受缓存数据类型、内存对齐、block 分配、模型实现和可用显存影响。</p><p>因此，MoE 报告缓存容量虽只有 5.88 GiB，却支持更多缓存 token，并不矛盾。vLLM 报告的是其运行时实现下的缓存容量指标，不能仅凭全注意力 K/V 理论字节数反推完整缓存容量。</p><h2 id="_8-结论" tabindex="-1">8. 结论 <a class="header-anchor" href="#_8-结论" aria-label="Permalink to &quot;8. 结论&quot;">​</a></h2><p>本次测试表明，FP8 Dense 与 FP8 MoE 的性能差异会随并发水平变化。</p><ol><li><strong>单请求解码速度接近。</strong> 并发 1 时，Dense TPOT 为 33.98 ms，MoE 为 35.02 ms，差距很小。</li><li><strong>MoE 在高并发下吞吐量更高。</strong> 并发 16 时，MoE 达 360.59 tok/s，约为 Dense 的 1.54 倍。</li><li><strong>MoE 扩展效率更好。</strong> 并发 16 时，MoE 线性扩展效率约 80.9%，Dense 为 52.3%。</li><li><strong>高并发下延迟差距更明显。</strong> 并发 16 时，MoE 平均 TTFT 和 E2E 都显著低于 Dense。</li><li><strong>理论计算量不能直接等同于实际速度。</strong> MoE 每 token 激活参数较少，但最终性能仍取决于 FP8 kernel、权重访存、专家调度和推理框架实现。</li></ol><p>总体来看，在当前硬件和 vLLM 配置下，Dense 在低并发时可提供与 MoE 接近的解码速度；并发增加后，MoE 更能维持吞吐量增长，并表现出更低平均延迟。</p><p>这些结论适用于本次测试配置，不应直接外推到其他 GPU、量化实现或推理框架。</p>`,87)])])}const c=e(d,[["render",i]]);export{x as __pageData,c as default};
